ALTER TABLE public.catalog_registry ADD COLUMN display_name text;
ALTER TABLE public.catalog_registry ADD COLUMN enabled boolean NOT NULL DEFAULT true;
ALTER TABLE public.catalog_registry ADD COLUMN overridden boolean NOT NULL DEFAULT false;
CREATE TABLE public.catalog_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),game_name text NOT NULL,actor_id uuid NOT NULL,before_data jsonb,after_data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.catalog_revisions TO authenticated;
GRANT ALL ON public.catalog_revisions TO service_role;
ALTER TABLE public.catalog_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_catalog_revisions ON public.catalog_revisions FOR SELECT TO authenticated USING(admin_is_unlocked());
CREATE OR REPLACE FUNCTION public.admin_catalog_edit(_game text,_display text,_url text,_category text,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prior catalog_registry; BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF length(_game) NOT BETWEEN 1 AND 200 OR length(_display) NOT BETWEEN 1 AND 200 OR _url !~ '^https://[^/@[:space:]]+([/?#]|$)' OR length(_url)>2000 OR length(_category)>50 THEN RAISE EXCEPTION 'Dados do jogo inválidos'; END IF; PERFORM consume_action_budget('admin_catalog',30,60); SELECT * INTO prior FROM catalog_registry WHERE game_name=_game FOR UPDATE; INSERT INTO catalog_registry(game_name,display_name,source_url,category,enabled,overridden) VALUES(_game,_display,_url,_category,_enabled,true) ON CONFLICT(game_name) DO UPDATE SET display_name=excluded.display_name,source_url=excluded.source_url,category=excluded.category,enabled=excluded.enabled,overridden=true,updated_at=now(); INSERT INTO catalog_revisions(game_name,actor_id,before_data,after_data) VALUES(_game,auth.uid(),to_jsonb(prior),jsonb_build_object('display_name',_display,'source_url',_url,'category',_category,'enabled',_enabled)); INSERT INTO admin_audit(actor_id,action,resource) VALUES(auth.uid(),'catalog_edit',_game); END $$;
REVOKE ALL ON FUNCTION public.admin_catalog_edit(text,text,text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_catalog_edit(text,text,text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_user_list(_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; RETURN coalesce((SELECT jsonb_agg(t) FROM (SELECT p.id,p.display_name,p.leaderboard_enabled,coalesce((SELECT sum(points) FROM xp_events x WHERE x.user_id=p.id),0) xp,coalesce((SELECT jsonb_agg(role) FROM user_roles r WHERE r.user_id=p.id),'[]'::jsonb) roles FROM profiles p ORDER BY p.display_name,p.id LIMIT 30 OFFSET greatest(0,_offset))t),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.admin_user_list(integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_user_list(integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_set_moderator(_user uuid,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=_user) THEN RAISE EXCEPTION 'Conta não encontrada'; END IF; IF _enabled THEN INSERT INTO user_roles(user_id,role) VALUES(_user,'moderator') ON CONFLICT DO NOTHING; ELSE DELETE FROM user_roles WHERE user_id=_user AND role='moderator'; END IF; INSERT INTO admin_audit(actor_id,action,resource,details) VALUES(auth.uid(),'moderator_role',_user::text,jsonb_build_object('enabled',_enabled)); END $$;
REVOKE ALL ON FUNCTION public.admin_set_moderator(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_set_moderator(uuid,boolean) TO authenticated;